def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count K-move paths through distinct orthogonally adjacent empty cells.

    H and W are between 1 and 10, and K is between 1 and 11.
    Every empty starting cell is allowed; reversed paths count separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        neighbors.append([
            index[(nr, nc)]
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            if (nr, nc) in index
        ])
    bits = [1 << i for i in range(len(cells))]

    def dfs(cell: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            bit = bits[nxt]
            if not visited & bit:
                total += dfs(nxt, remaining - 1, visited | bit)
        return total

    return sum(dfs(start, K, bits[start]) for start in range(len(cells)))

