from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return n+1 counts modulo 998244353. The constraints are
    1 <= n <= 10, 1 <= m <= 100, and len(s) == n.
    """
    mod = 998244353
    positions = {}
    for i, char in enumerate(s):
        positions[char] = positions.get(char, 0) | (1 << i)

    # A bit at i records an increase between adjacent entries of the
    # LCS row for prefixes s[:i] and s[:i+1]. Thus only 2**n rows exist.
    size = 1 << n
    transitions = []
    for state in range(size):
        counts = {state: 26 - len(positions)}
        for matches in positions.values():
            x = state | matches
            target = x & ~(x - ((state << 1) | 1))
            counts[target] = counts.get(target, 0) + 1
        transitions.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    next_dp[target] += count * multiplicity
        dp = [count % mod for count in next_dp]

    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        answer[state.bit_count()] += count
    return [count % mod for count in answer]

