def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions and replacements can turn s into t
    using at most k operations.

    Keep the farthest reachable source position on each edit-graph diagonal
    after each number of edits, extending every state across equal characters.
    There are O(k**2) frontier states and O(k * (len(s) + len(t))) work,
    with O(k) additional space.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t or max(n, m) <= k:
        return True

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    # A diagonal is x - y, where x and y are consumed prefix lengths.
    frontier = {0: x}
    for edits in range(1, k + 1):
        next_frontier = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                # Delete a source character.
                d = diagonal + 1
                next_frontier[d] = max(next_frontier.get(d, -1), x + 1)
            if y < m:
                # Insert the next target character.
                d = diagonal - 1
                next_frontier[d] = max(next_frontier.get(d, -1), x)
            if x < n and y < m:
                # Replace the next source character.
                next_frontier[diagonal] = max(
                    next_frontier.get(diagonal, -1), x + 1
                )

        frontier = {}
        for diagonal, x in next_frontier.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            # The remaining length difference is an unavoidable edit cost.
            if abs((n - x) - (m - y)) <= k - edits:
                frontier[diagonal] = x
        if not frontier:
            return False
    return False

