from math import isqrt


def find_largest_400_number(a: int) -> int:
    """Find the largest number <= a with exactly two distinct prime factors,
    each occurring to an even positive exponent.

    Such a number is precisely the square of an integer having exactly two
    distinct prime factors. Search the possible roots in descending order.
    The input bound ensures that every root is at most 1,000,000.
    """
    root = isqrt(a)
    while root >= 6:
        remaining = root
        distinct = 0
        divisor = 2
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                distinct += 1
                if distinct > 2:
                    break
                while remaining % divisor == 0:
                    remaining //= divisor
            divisor = 3 if divisor == 2 else divisor + 2
        else:
            if remaining > 1:
                distinct += 1
            if distinct == 2:
                return root * root
        root -= 1
    # The documented domain starts at 36, so root 6 always supplies a result.
    raise ValueError("a must be at least 36")

