def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k deletable nonempty substrings.

    A good string can be emptied by deleting equal pairs and triples ABC.
    Equivalently, its three character counts have the same parity.
    Return the count modulo 998244353, for 1 <= n <= 50.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix classes differ. The largest possible number of
    # equal-class prefix pairs is attained by alternating two classes.
    if k > n * n // 4:
        return 0

    # A, B, C are the three nonzero elements of the Klein four group.
    # Equal prefix XORs delimit precisely the good substrings.
    # Normalize each state so the current prefix is class zero. This
    # removes the need to store the current XOR as another state dimension.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        nxt = {}
        choices = (1, 2, 3) if ch == '?' else ({'A': 1, 'B': 2, 'C': 3}[ch],)
        for (a, b, c, d), ways in dp.items():
            for v in choices:
                if v == 1:
                    state = (b + 1, a, d, c)
                elif v == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for counts, ways in dp.items():
        good = sum(x * (x - 1) // 2 for x in counts)
        if good >= k:
            answer += ways
    return answer % mod

