def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum the products of all positive integer sequences with the prescribed
    reduced adjacent numerator-denominator products and overall gcd one.

    Each a[i] is between 1 and 1000; 2 <= n <= 1000.
    The result is returned modulo 998244353.
    """
    mod = 998244353
    exponents = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            count = 0
            while value % p == 0:
                value //= p
                count += 1
            if count:
                if p not in exponents:
                    exponents[p] = [0] * (n - 1)
                exponents[p][i] = count
            p += 1
        if value > 1:
            if value not in exponents:
                exponents[value] = [0] * (n - 1)
            exponents[value][i] += 1

    answer = 1
    for prime, steps in exponents.items():
        total = sum(steps)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * prime % mod

        # dp[h] sums products for normalized prefixes ending at height h.
        # Normalization subtracts the minimum exponent in the prefix.
        dp = [1]
        for i, step in enumerate(steps):
            if step == 0:
                # A zero exponent has only one orientation.
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue
            next_dp = [0] * (len(dp) + step)
            shift_factors = [1] + [
                pow(prime, (i + 1) * shift, mod)
                for shift in range(1, step + 1)
            ]
            for height, weight in enumerate(dp):
                up = height + step
                next_dp[up] = (next_dp[up] + weight * powers[up]) % mod
                if height >= step:
                    down = height - step
                    next_dp[down] = (
                        next_dp[down] + weight * powers[down]
                    ) % mod
                else:
                    # A new minimum raises all i+1 old exponents.
                    next_dp[0] = (
                        next_dp[0] + weight * shift_factors[step - height]
                    ) % mod
            dp = next_dp
        answer = answer * (sum(dp) % mod) % mod
    return answer

