from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return n+1 counts modulo 998244353, for LCS lengths 0 through n.
    Constraints: 1 <= n <= 10, 1 <= m <= 100, and len(s) == n.
    """
    mod = 998244353
    size = 1 << n
    full = size - 1
    matches = {}
    for i, char in enumerate(s):
        matches[char] = matches.get(char, 0) | (1 << i)

    # A state encodes adjacent differences of the LCS DP row for s's
    # prefixes. Each difference is zero or one, so n bits suffice.
    transitions = []
    for state in range(size):
        counts = {state: 26 - len(matches)}
        for match in matches.values():
            x = state | match
            target = x & ~(x - ((state << 1) | 1)) & full
            counts[target] = counts.get(target, 0) + 1
        transitions.append([(target, count) for target, count in counts.items() if count])

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    next_dp[target] += count * multiplicity
        dp = [count % mod for count in next_dp]

    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + count) % mod
    return answer

