def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k reducible nonempty substrings.

    Identical pairs and ABC triples may be deleted in any positions.
    Return the answer modulo 998244353, for 1 <= n <= 50.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix states differ. Concentrating their visits on two
    # alternating states maximizes the number of equal-prefix pairs.
    if k > n * n // 4:
        return 0

    # Map A, B, C to the three nonzero elements of (Z/2Z)^2.
    # A substring reduces to empty iff its three counts have equal parity,
    # equivalently its mapped xor is zero. Thus its two prefix states agree.
    # Translate all prefix states by the current one, keeping it at state 0.
    # The tuple records visits to each of the four translated states.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        following = {}
        choices = (1, 2, 3) if ch == '?' else ({'A': 1, 'B': 2, 'C': 3}[ch],)
        for (a, b, c, d), ways in dp.items():
            for step in choices:
                if step == 1:
                    state = (b + 1, a, d, c)
                elif step == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                following[state] = (following.get(state, 0) + ways) % mod
        dp = following
    return sum(ways for counts, ways in dp.items()
               if sum(c * (c - 1) // 2 for c in counts) >= k) % mod

