def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions, modulo 998244353.

    Each edge-sharing pair must have different digits. The grid has at
    most 200 cells; fixed digits cannot be changed.
    """
    mod = 998244353
    # Sweep along the longer dimension to minimize the frontier width.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Each two-bit field records the most recently visited cell in its
    # column. Zero denotes a column not visited yet in the first row.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            left_shift = shift - 2
            choices = (1, 2, 3) if grid[r][c] == "?" else (int(grid[r][c]),)
            next_dp = {}
            for state, ways in dp.items():
                above = (state >> shift) & 3
                left = ((state >> left_shift) & 3) if c else 0
                cleared = state - (above << shift)
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = cleared | (colour << shift)
                        next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-color completions modulo 998244353.

    Every pair of edge-sharing cells must contain different digits.
    H and W are positive and H * W <= 200; fixed cells are 1, 2, or 3.
    """
    mod = 998244353
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject incompatible fixed neighbors before building any frontier states.
    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if r and grid[r - 1][c] == value:
                    return 0
                if c and grid[r][c - 1] == value:
                    return 0

    # Two bits per column store the latest color in that column. Zero marks
    # a column not yet visited. At each step only the upper and left cells
    # can already have been colored among the new cell's neighbors.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            clear = ~(3 << shift)
            fixed = grid[r][c]
            choices = (1, 2, 3) if fixed == '?' else (int(fixed),)
            nxt = {}
            for mask, count in dp.items():
                upper = (mask >> shift) & 3
                left = ((mask >> (shift - 2)) & 3) if c else 0
                base = mask & clear
                for color in choices:
                    if color != upper and color != left:
                        state = base | (color << shift)
                        nxt[state] = (nxt.get(state, 0) + count) % mod
            if not nxt:
                return 0
            dp = nxt
    return sum(dp.values()) % mod

