from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the minimum cost to cover every section, or -1 if impossible.

    A sensor belongs to one section. Sensors of either type may be combined,
    overlap, or extend beyond that section. Each sensor tuple contains its
    coverage length, cost, and available count.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    # Extra sensors beyond an all-one-type covering can never improve a solution.
    k1 = min(k1, sum((d + l1 - 1) // l1 for d in sections))
    k2 = min(k2, sum((d + l2 - 1) // l2 for d in sections))
    if k1 > k2:
        l1, c1, k1, l2, c2, k2 = l2, c2, k2, l1, c1, k1

    # dp[a] is the fewest type-2 sensors needed using exactly a type-1
    # sensors on the sections already processed. Larger second counts at
    # the same a cannot help any later section.
    unreachable = k2 + 1
    dp = [0]
    for length in sections:
        limit = min(k1, (length + l1 - 1) // l1)
        options = []
        for a in range(limit + 1):
            b = max(0, (length - a * l1 + l2 - 1) // l2)
            if b <= k2:
                options.append((a, b))
        if not options:
            return -1
        next_dp = [unreachable] * (min(k1, len(dp) - 1 + limit) + 1)
        for used, previous in enumerate(dp):
            if previous == unreachable:
                continue
            for a, b in options:
                total = used + a
                if total > k1:
                    break
                second = previous + b
                if second < next_dp[total]:
                    next_dp[total] = second
        if min(next_dp) == unreachable:
            return -1
        dp = next_dp
    return min(a * c1 + b * c2 for a, b in enumerate(dp) if b <= k2)

