def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper completions of the grid modulo 998244353.

    Each '?' can be replaced by 1, 2, or 3; edge-adjacent cells
    must have different digits. The grid has at most 200 cells.
    """
    mod = 998244353
    # Use the shorter dimension as the frontier (at most 14 cells).
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject incompatible fixed neighbours before constructing any states.
    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if r and grid[r - 1][c] == value:
                    return 0
                if c and grid[r][c - 1] == value:
                    return 0

    # Two bits per frontier cell. Zero denotes an unfilled cell in
    # the initial row; the other values are the three actual colours.
    dp = {0: 1}
    for row in grid:
        for c, char in enumerate(row):
            shift = 2 * c
            place = 1 << shift
            choices = (1, 2, 3) if char == '?' else (int(char),)
            nxt = {}
            for state, ways in dp.items():
                above = (state >> shift) & 3
                left = ((state >> (shift - 2)) & 3) if c else 0
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = state + (colour - above) * place
                        nxt[new_state] = (nxt.get(new_state, 0) + ways) % mod
            dp = nxt
            if not dp:
                return 0
    return sum(dp.values()) % mod
